INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(7509, 'koKR', '', 'Zanieś Niewypalone starożytne ostrze do leża Onyxii i zmierz się z nią w walce.$B$BDo rozgrzania ostrza trzeba użyć podstępu. Podczas walki smoczyca z pewnością spróbuje spopielić cię ognistym oddechem. Musisz wbić Niewypalone starożytne ostrze w ziemię w pobliżu i liczyć, że ognisty oddech je rozgrzeje. Jeśli to przeżyjesz, podnieś Rozgrzane już starożytne ostrze i dobij smoczycę.$B$BWbij Rozgrzane starożytne ostrze w jej tlące się zwłoki, a otrzymasz Zahartowane starożytne ostrze.', 'Musisz sprawić, by Onyxia zionęła ogniem na Niewypalone starożytne ostrze. Gdy to się stanie, podnieś Rozgrzane starożytne ostrze. Uważaj: Rozgrzane starożytne ostrze nie pozostanie gorące w nieskończoność – liczy się czas.$B$BOstatnim krokiem przed powrotem do mnie jest zabicie bestii i wbicie Rozgrzanego starożytnego ostrza w jej zwłoki.$B$BUczyń to, a Quel\'Serrar będzie twój.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(7509, 'koKR', '<Lydros mamrocze coś niezrozumiale.>$B$BZgodnie z obietnicą, $N, oto ostrze Quel\'Serrar.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(7509, 'koKR', 'Może pewnego dnia ktoś inny dzierżyć będzie to pryzmatyczne ostrze.', 0);
