INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(8286, 'koKR', '', 'Cóż za szczęśliwy traf. Zwykle muszę opuszczać leże, żeby się pożywić.', 0),
(8287, 'koKR', '', 'Znaj swoje miejsce, śmiertelniku!', 0),
(8288, 'koKR', '', 'Ten bezsensowny wysiłek mnie nudzi. Spopielę was wszystkich z góry!', 0),
(8290, 'koKR', '', 'Zdaje się, że potrzebujecie kolejnej lekcji, śmiertelnicy!', 0),
(8570, 'koKR', '', 'Chcecie odciągnąć mnie od mojego lęgu? Zapłacicie za swoją zuchwałość!', 0),
(36542, 'koKR', '%s bierze głęboki oddech...', '', 0);
